SELECT * FROM device_commands
WHERE agent_code = #{agentCode} AND command_id = #{commandId}
  AND command_type = #{commandType} AND attempt_no = #{attemptNo}

SELECT * FROM device_commands
WHERE command_type = 'TASK_CANCEL' AND command_status IN ('PENDING', 'SENT')
  AND created_at < #{threshold}

SELECT * FROM device_commands
WHERE agent_code = #{agentCode}
ORDER BY created_at DESC
LIMIT #{limit}

mapper.update:
UPDATE device_commands
SET command_status = #{status}, response_payload = COALESCE(#{responsePayload}, response_payload),
    updated_at = CURRENT_TIMESTAMP
WHERE agent_code = #{agentCode} AND command_id = #{commandId}
  AND command_type = #{commandType} AND attempt_no = #{attemptNo}
  AND (#{status} NOT IN ('SENT', 'DELIVERY_FAILED') OR command_status IN ('PENDING', 'DELIVERY_FAILED'))
